require_once __DIR__.'/../../app/layout.php';require_role('candidate');$uid=(int)current_user()['id'];$st=db()->prepare('SELECT * FROM candidate_profiles WHERE user_id=?');$st->execute([$uid]);$profile=$st->fetch()?:[];$st=db()->prepare('SELECT COUNT(*) FROM applications WHERE candidate_id=?');$st->execute([$uid]);$total=(int)$st->fetchColumn();$st=db()->prepare("SELECT a.*,j.title,j.work_type,COALESCE(cp.company_name,u.name) company FROM applications a JOIN jobs j ON j.id=a.job_id JOIN users u ON u.id=j.company_id LEFT JOIN company_profiles cp ON cp.user_id=u.id WHERE a.candidate_id=? ORDER BY a.created_at DESC LIMIT 6");$st->execute([$uid]);$apps=$st->fetchAll();page_header('Dashboard pencari kerja');?>
<section class="dashboard-head"><div class="container"><span class="eyebrow">RUANG KARIERMU</span><h1>Halo, <?=e(current_user()['name'])?> 👋</h1><p>Setiap langkah kecil adalah kemajuan. Yuk, lanjutkan perjalanan kariermu.</p><a class="btn btn-primary" href="<?=e(url('candidate/profile.php'))?>">Lengkapi profil ↗</a></div></section><section class="section"><div class="container"><div class="metrics"><div><small>Total lamaran</small><b><?=$total?></b><span>Lamaran terkirim</span></div><div><small>Profil karier</small><b><?=!empty($profile['headline'])?'✓':'—'?></b><span><?=!empty($profile['headline'])?'Sudah mulai lengkap':'Tambahkan ringkasan'?></span></div><div><small>Preferensi</small><b><?=!empty($profile['remote_preference'])?'Remote':'Atur'?></b><span>Jenis kerja yang diminati</span></div></div><div class="dashboard-grid"><div class="panel"><div class="panel-heading"><h2>Lamaran terbaru</h2><a class="link" href="<?=e(url('candidate/applications.php'))?>">Lihat semua →</a></div><?php if(!$apps):?><div class="empty"><h3>Belum ada lamaran</h3><p>Mulai temukan pekerjaan yang sesuai.</p><a class="btn btn-primary" href="<?=e(url('jobs.php'))?>">Cari lowongan</a></div><?php else:?><div class="table-wrap"><table><tr><th>Posisi</th><th>Perusahaan</th><th>Status</th></tr><?php foreach($apps as $a):?><tr><td><a class="link" href="<?=e(url('job.php?id='.(int)$a['job_id']))?>"><?=e($a['title'])?></a><small><?=e($a['work_type'])?></small></td><td><?=e($a['company'])?></td><td><span class="badge <?=e(badge_class($a['status']))?>"><?=e($a['status'])?></span></td></tr><?php endforeach;?></table></div><?php endif;?></div><div class="panel"><h2>Akses cepat</h2><div class="quick"><a href="<?=e(url('candidate/profile.php'))?>">Profil & CV <span>→</span></a><a href="<?=e(url('training.php'))?>">Pelatihan <span>→</span></a><a href="<?=e(url('freelance.php'))?>">Jasa freelance <span>→</span></a></div></div></div></div></section>
